function C:StartScenario()
  if not coroutine.isyieldable() then spawn(C.StartScenario, self) return end
  PostEffectManager:SetShader("Kakusei")
  PostEffectManager:SetShaderWeight_1(1)
  EventManager:ObiActive(false)
  AudioManager:PlayBgmByType("BGM_event_emo", true)
  C.super.StartScenario(self)
  UniTask.Delay(Constants.MIDDLE, false, "Update", nil, false)
  spawn(function() ImageViewerHelper.OpenImageViewer(ImageViewerHelper.LoadResourcesList():Find(function(r) return r.FileName == "kyouso_ending" end).FileName) end)
  Settings:addImage("kyouso_ending", true)
  WindowManager:GetWindowFromApp("ImageViewer"):Maximize()
  WindowManager:GetWindowFromApp("ImageViewer"):UnMovable()
  UniTask.Delay(Constants.SLOW, false, "Update", nil, false)
  NgoEvent.DelaySkippable(Constants.SLOW * 5)
  NotificationManager:osimai()
  AchievementStatsUpdater.UpdateStats("Ending_Kyouso")
end

return C
